contentRule.content:
##sourceurl\s*=\s*"([^"]+)"##$1##
@js:r=org.jsoup.Jsoup.parse(java.ajax(result));
r.select('a>*,header,.header,#header,.head,#head,.foot,#foot,:not(img,br,p,a,:matchesOwn([\\s\\S]{200}),:has(p,br,img,:matchesOwn([\\s\\S]{200}),div:matchesOwn(，|。)+div:matchesOwn(，|。))),:matchesOwn(，|。) :not(img,br,a,:has(img)),footer,.footer,#footer,:not(:has(p:matchesOwn([\\s\\S]{200}),p+p,:has(>p)+:has(>p))) p,:has(p+p,:has(p)+:has(p)):not(:contains(。)) p,img[src=""]').remove();

r=String(r).replace(/<([a-z]+)[^>]*"-\d+"[^>]*>[^<]+<\/\1>|[^<>]*<a[^<]+<\/a>[^<]*|&lt[; ]?([a-z]+)(?:[^<>&"]|"[^"]+")*&gt[; ]?(?:[^<>&]|&nbsp;)*&lt[; ]?\/\2&gt[; ]?|&lt[; ]?[a-z]+(?:[^<>&"]|"[^"]+")*&gt[; ]?|[☯📑⚙️︴]/g,"").replace(new RegExp("("+title.replace(/^第[一二三四五六七八九十百千万〇零0-9]+[章节回話话][\s：:]*(?=\S)/,"").replace(/[*$|?+\\\^\[\](){}]/g,".")+"|"+java.get("b")+")","g"),"☯⚙️$1⚙️☯");

(/;&nbsp;/.test(r)?r.replace(/>\n*(?=[^;<\n]+\S\s*<)/g,">︴"):/　　/.test(r)?r.replace(/>\n*(?=[^　\n<]+\S\s*<)/g,">︴"):r)+"📑"

contentRule.nextContentUrl:
@js:q=java.getElement("a:matches(第二[頁页])||a:matches([下上][一\\s]*[頁页篇章回节節话話]):not([href~=^#|javascript:])");
if(q.size()){
s=q.select("a:contains(上)").attr("href");
x=q.select("a:contains(下)").attr("href");
s.length||x.length?s.length<=x.length?x:"":q.attr("href")}

